func FillWithKEVuln(r *models.ScanResult, cnf config.KEVulnConf, logOpts logging.LogOpts) error {
	client, err := newGoKEVulnDBClient(&cnf, logOpts)
	if err != nil {
		return err
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	nKEV := 0
	if client.driver == nil {
		var cveIDs []string
		for cveID := range r.ScannedCves {
			cveIDs = append(cveIDs, cveID)
		}
		prefix, err := util.URLPathJoin(client.baseURL, "cves")
		if err != nil {
			return err
		}
		responses, err := getKEVulnsViaHTTP(cveIDs, prefix)
		if err != nil {
			return err
		}
		for _, res := range responses {
			kevulns := kevulndb.Response{}
			if err := json.Unmarshal([]byte(res.json), &kevulns); err != nil {
				return err
			}
			v, ok := r.ScannedCves[res.request.cveID]
			if !ok {
				continue
			}
			v.KEVs = toKEVs(kevulns)
			if len(v.KEVs) > 0 {
				nKEV++
			}
			r.ScannedCves[res.request.cveID] = v
		}
	} else {
		for cveID, vuln := range r.ScannedCves {
			if cveID == "" {
				continue
			}
			kevulns, err := client.driver.GetKEVByCveID(cveID)
			if err != nil {
				return err
			}
			vuln.KEVs = toKEVs(kevulns)
			if len(vuln.KEVs) > 0 {
				nKEV++
			}
			r.ScannedCves[cveID] = vuln
		}
	}

	logging.Log.Infof("%s: Known Exploited Vulnerabilities are detected for %d CVEs", r.FormatServerName(), nKEV)
	return nil
}

func toKEVs(source kevulndb.Response) []models.KEV {
	var result []models.KEV
	for _, entry := range source.CISA {
		var dueDate *time.Time
		if !entry.DueDate.IsZero() && entry.DueDate.Year() > 1 {
			due := entry.DueDate
			dueDate = &due
		}
		result = append(result, models.KEV{
			Type: models.CISAKEVType, VendorProject: entry.VendorProject,
			Product: entry.Product, VulnerabilityName: entry.VulnerabilityName,
			ShortDescription: entry.ShortDescription, RequiredAction: entry.RequiredAction,
			KnownRansomwareCampaignUse: entry.KnownRansomwareCampaignUse,
			DateAdded:                  entry.DateAdded, DueDate: dueDate,
			CISA: &models.CISAKEV{Note: entry.Notes},
		})
	}
	for _, entry := range source.VulnCheck {
		var dueDate *time.Time
		if entry.DueDate != nil && !entry.DueDate.IsZero() && entry.DueDate.Year() > 1 {
			dueDate = entry.DueDate
		}
		kev := models.KEV{
			Type: models.VulnCheckKEVType, VendorProject: entry.VendorProject,
			Product: entry.Product, VulnerabilityName: entry.Name,
			ShortDescription: entry.Description, RequiredAction: entry.RequiredAction,
			KnownRansomwareCampaignUse: entry.KnownRansomwareCampaignUse,
			DateAdded:                  entry.DateAdded, DueDate: dueDate,
			VulnCheck: &models.VulnCheckKEV{},
		}
		for _, xdb := range entry.VulnCheckXDB {
			kev.VulnCheck.XDB = append(kev.VulnCheck.XDB, models.VulnCheckXDB{
				XDBID: xdb.XDBID, XDBURL: xdb.XDBURL, DateAdded: xdb.DateAdded,
				ExploitType: xdb.ExploitType, CloneSSHURL: xdb.CloneSSHURL,
			})
